import { readFileSync, writeFileSync } from "node:fs";

const [input, output] = process.argv.slice(2);
if (!input || !output) throw new Error("usage: generate-mdct-tables.mjs INPUT OUTPUT");
const fixture = JSON.parse(readFileSync(input, "utf8"));
if (fixture.pin !== "22244de5a79bd1d6d623c32e72bf1954b56235be") throw new Error("unexpected libopus pin");
if (fixture.plans.map((plan) => plan.frame).join(",") !== "120,240,480,960") throw new Error("unexpected plans");

const values = (items) => {
  const lines = [];
  for (let index = 0; index < items.length; index += 12) {
    lines.push(`\t\t${items.slice(index, index + 12).join(", ")},`);
  }
  return lines.join("\n");
};
const fields = [
  ["trig", "trig"],
  ["twiddleR", "twiddle_r"],
  ["twiddleI", "twiddle_i"],
  ["bitrev", "bitrev"],
  ["factors", "factors"],
];
const plans = fixture.plans.map((plan) => `{
\tframeSampleCount: ${plan.frame},
${fields.map(([goName, jsonName]) => `\t${goName}: []uint32{\n${values(plan[jsonName])}\n\t},`).join("\n")}
}`).join(",\n");
const source = `// Code generated by testdata/short-plc/generate-mdct-tables.mjs; DO NOT EDIT.
// SPDX-FileCopyrightText: 2003-2004 Mark Borgerding
// SPDX-FileCopyrightText: 2005-2008 Xiph.Org Foundation
// SPDX-FileCopyrightText: 2008 CSIRO
// SPDX-License-Identifier: BSD-2-Clause

package celt

type decoderTransformTable struct {
\tframeSampleCount int
\ttrig             []uint32
\ttwiddleR         []uint32
\ttwiddleI         []uint32
\tbitrev           []uint32
\tfactors          []uint32
}

var decoderTransformTables = [...]decoderTransformTable{ //nolint:gochecknoglobals
${plans},
}
`;
writeFileSync(output, source);
